import React, { useState } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { QRCodeCanvas } from 'qrcode.react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';

const Alta = () => {
    const [verificationUrl, setVerificationUrl] = useState('');
    const [sessionId, setSessionId] = useState('');
    const [qrVisible, setQrVisible] = useState(false);
    const [issuanceOfferUrl, setIssuanceOfferUrl] = useState('');
    const [issuanceQrVisible, setIssuanceQrVisible] = useState(false);

    const navigate = useNavigate();

    const startTwoCredsVerification = async () => {
        try {
            const response = await axios.post('http://localhost:3001/verification/offer2creds', {});
            setVerificationUrl(response.data.verificationUrl);
            setSessionId(response.data.state);
            setQrVisible(true);

            const interval = setInterval(async () => {
                const statusRes = await axios.get(`http://localhost:3001/verification/session/${response.data.state}`);
                const { status } = statusRes.data;
                if (status === 'verified') {
                    clearInterval(interval);
                    toast.success('¡Verificación completada! Emisión de credencial en proceso...');
                    const issuanceRes = await axios.post('http://localhost:3001/issuance/offer', { stateId: response.data.state });
                    setIssuanceOfferUrl(issuanceRes.data.issuanceOfferUrl);
                    setIssuanceQrVisible(true);
                } else if (status === 'failed') {
                    clearInterval(interval);
                    toast.error('La verificación ha fallado.');
                }
            }, 5000);
        } catch (error) {
            console.error(error);
            toast.error('Error iniciando verificación para el alta.');
        }
    };

    // Variants para animaciones con Framer Motion
    const containerVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.5, ease: 'easeOut' }
        }
    };

    const cardVariants = {
        hidden: { opacity: 0, scale: 0.95 },
        visible: {
            opacity: 1,
            scale: 1,
            transition: { type: 'spring', stiffness: 120, damping: 15 }
        }
    };

    return (
        <motion.div
            className="flex flex-col items-center justify-center min-h-[80vh] p-4 bg-white text-neutralDark"
            initial="hidden"
            animate="visible"
            variants={containerVariants}
        >
            <h2 className="font-headings text-3xl md:text-4xl mb-6 text-primary font-bold">
                Proceso de Alta
            </h2>
            <p className="font-body text-lg md:text-xl mb-6 text-justify max-w-xl leading-relaxed">
                Para darse de alta en la Seguridad Social necesita presentar dos credenciales:
                <br /><br />
                - Credencial de Identidad (CustomIdentityCredential)
                <br />
                - Prueba de Residencia (ProofOfResidenceCredential)
                <br /><br />
                Al iniciar este proceso se le pedirá escanear un QR y presentar ambas credenciales.
                <br /><br />
                Una vez validadas, procederemos a la emisión de su credencial de Alta en la Seguridad Social.
            </p>

            {!qrVisible && !issuanceQrVisible && (
                <motion.button
                    onClick={startTwoCredsVerification}
                    className="px-7 py-3 bg-primary text-white rounded-full hover:bg-secondary transition font-body text-lg font-semibold focus:outline-none"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                >
                    Iniciar verificación para el alta
                </motion.button>
            )}

            {qrVisible && !issuanceQrVisible && (
                <motion.div
                    className="flex flex-col items-center mt-7 p-7 bg-white rounded-xl shadow-lg"
                    variants={cardVariants}
                    initial="hidden"
                    animate="visible"
                >
                    <p className="font-body mb-4 text-neutralDark text-base">
                        Escanea este código QR con tu wallet y presenta las 2 credenciales requeridas:
                    </p>
                    <div className="hover:scale-105 transition-transform duration-200 ease-in-out">
                        <QRCodeCanvas value={verificationUrl} size={256} className="mb-4" />
                    </div>
                    <p className="font-body text-sm text-neutralDark animate-pulse">
                        Esperando verificación de ambas credenciales...
                    </p>
                </motion.div>
            )}

            {issuanceQrVisible && (
                <motion.div
                    className="flex flex-col items-center mt-6 p-6 bg-white rounded-xl shadow-lg"
                    variants={cardVariants}
                    initial="hidden"
                    animate="visible"
                >
                    <p className="font-body mb-4 text-neutralDark text-base">
                        Verificación completada. Ahora escanee este QR para recibir su credencial Alta_Seguridad_Social:
                    </p>
                    <div className="hover:scale-105 transition-transform duration-200 ease-in-out">
                        <QRCodeCanvas value={issuanceOfferUrl} size={256} className="mb-4" />
                    </div>
                    <p className="font-body text-sm text-neutralDark mb-4">Escanee para emitir la credencial en su wallet.</p>
                    <button
                        className="px-6 py-3 bg-primary text-white rounded-full hover:bg-secondary hover:scale-105 transition-transform duration-200 font-body font-semibold text-base"
                        onClick={() => navigate('/dashboard')}
                    >
                        Volver al Dashboard
                    </button>
                </motion.div>
            )}
        </motion.div>
    );
};

export default Alta;

