    // Por simplicidad, se deja así, o ajusta si tu backend lo devolviese en userData.

    return (
        <div className="min-h-[80vh] p-4 bg-neutralLight fade-in-scale flex flex-col items-center">
            <div className="bg-white w-full max-w-4xl p-8 rounded-xl shadow-lg">
                <div className="flex flex-col md:flex-row items-center justify-between mb-8">
