// src/pages/Register/Register.js

import React, { useState, useEffect, useCallback } from 'react';
import { useDispatch } from 'react-redux';
import { startVerification, checkSessionStatus } from '../../services/api';
import { verifyUser } from '../../store/authSlice';
import { useNavigate } from 'react-router-dom';
import { QRCodeCanvas } from 'qrcode.react';
import { toast } from 'react-toastify';
import { userSchema } from '../../utils/validation';
import { motion } from 'framer-motion';
import './Register.css';

const Register = () => {
  const [offerURL, setOfferURL] = useState('');
  const [sessionId, setSessionId] = useState('');
  const [qrVisible, setQrVisible] = useState(false);
  const [isLoadingQRCode, setIsLoadingQRCode] = useState(false);
  const [isVerifiedAnimation, setIsVerifiedAnimation] = useState(false);

  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleVerifyDNI = async () => {
    try {
      const { verificationUrl, sessionId } = await startVerification();
      setIsLoadingQRCode(true);
      setTimeout(() => {
        setOfferURL(verificationUrl);
        setSessionId(sessionId);
        setIsLoadingQRCode(false);
        setQrVisible(true);
        toast.info('Escanee el código QR con su wallet');
      }, 3000);
    } catch (error) {
      console.error(error);
      toast.error('Error iniciando verificación');
    }
  };

  const checkVerificationStatusCallback = useCallback(async () => {
    if (!sessionId) return;
    try {
      const data = await checkSessionStatus(sessionId);
      const { status, token, user } = data;
      if (status === 'verified' && token && user) {
        const result = userSchema.safeParse(user);
        if (!result.success) {
          toast.error('Datos de usuario inválidos recibidos del backend.');
          return;
        }
        setIsVerifiedAnimation(true);
        setTimeout(() => {
          localStorage.setItem('token', token);
          localStorage.setItem('user', JSON.stringify(user));
          dispatch(verifyUser({ user, token }));
          toast.success('Verificación exitosa!');
          navigate('/dashboard');
        }, 2000);
      } else if (status === 'failed') {
        toast.error('Verificación fallida.');
      }
    } catch (error) {
      console.error(error);
    }
  }, [sessionId, dispatch, navigate]);

  useEffect(() => {
    let interval;
    if (sessionId) {
      interval = setInterval(checkVerificationStatusCallback, 5000);
    }
    return () => clearInterval(interval);
  }, [sessionId, checkVerificationStatusCallback]);

  const containerVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.5, ease: 'easeOut' }
    }
  };

  const cardVariants = {
    hidden: { opacity: 0, scale: 0.95 },
    visible: {
      opacity: 1,
      scale: 1,
      transition: { type: 'spring', stiffness: 120, damping: 15 }
    }
  };

  return (
    <motion.div
      className="flex flex-col items-center justify-center min-h-[80vh] p-4 bg-white"
      initial="hidden"
      animate="visible"
      variants={containerVariants}
    >
      <h2 className="font-headings text-3xl md:text-4xl mb-6 text-primary font-bold">Verificación DNI</h2>

      {isVerifiedAnimation && (
        <motion.div
          className="verification-check-animation flex flex-col items-center justify-center"
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1, transition: { duration: 0.5, ease: 'easeOut' } }}
        >
          <div className="checkmark flex items-center justify-center">
          </div>
          <p className="font-body text-lg mt-2 text-primary font-semibold">Credencial Verificada</p>
        </motion.div>
      )}

      {!isVerifiedAnimation && (
        <>
          {!qrVisible && !isLoadingQRCode && (
            <motion.button
              onClick={handleVerifyDNI}
              className="px-6 py-3 bg-primary text-white rounded-full hover:bg-secondary transition font-body text-lg font-semibold"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Verificar DNI
            </motion.button>
          )}

          {isLoadingQRCode && (
            <motion.div
              className="loading-animation flex flex-col items-center"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1, transition: { duration: 0.5 } }}
            >
              <div className="spinner"></div>
              <p className="font-body text-neutralDark mt-2 text-base">Generando QR...</p>
            </motion.div>
          )}

          {qrVisible && !isLoadingQRCode && (
            <motion.div
              className="flex flex-col items-center mt-6 p-6 bg-white rounded-xl shadow-lg"
              variants={cardVariants}
              initial="hidden"
              animate="visible"
            >
              <p className="font-body mb-4 text-neutralDark text-base">Escanea este código QR con tu wallet:</p>
              <motion.div whileHover={{ scale: 1.05 }} transition={{ duration: 0.2 }}>
                <QRCodeCanvas value={offerURL} size={256} className="mb-4" />
              </motion.div>
              <p className="font-body text-sm text-neutralDark animate-pulse">Esperando verificación...</p>
            </motion.div>
          )}
        </>
      )}
    </motion.div>
  );
};

export default Register;

